import os, csv, json
from pathlib import Path
from collections import deque

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
csv_path = DIR / "20190114_pipeline.csv"

adj = {}
with open(csv_path, newline="", encoding="utf-8-sig") as f:
    for row in csv.DictReader(f):
        s = row.get("source") or row.get("源") or ""
        t = row.get("target") or row.get("目标") or ""
        p = row.get("pipeline") or row.get("管道") or row.get("管线") or ""
        if not s or not t:
            s = list(row.values())[0]; t = list(row.values())[1]; p = list(row.values())[2] if len(row.values()) > 2 else ""
        adj.setdefault(s, []).append((t, p))

def bfs(start, goal):
    q = deque([(start, [])])
    seen = {start}
    while q:
        node, path = q.popleft()
        if node == goal:
            return path
        for nxt, pipe in adj.get(node, []):
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, path + [{"source": node, "target": nxt, "pipeline": pipe}]))
    return None

out = {}
for src in ["靖边站", "榆林站"]:
    out[src] = bfs(src, "南通站")
print(json.dumps(out, ensure_ascii=False, default=str))

